// ─────────────────────────────────────────────────────────────
// READ CONFIG FILES
// To change platform sizes → edit media/platforms.json
// To change watermark      → edit media/watermark.json
// ─────────────────────────────────────────────────────────────
const fs   = require('fs');
const path = require('path');

const platformsCfg = JSON.parse(fs.readFileSync('/data/media/platforms.json', 'utf8'));
const watermarkCfg = JSON.parse(fs.readFileSync('/data/media/watermark.json', 'utf8'));

const item      = $input.first();
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) throw new Error('No image found. Please upload an image.');

const imageBinary = item.binary[binaryKey];
const origName    = (imageBinary.fileName || 'image').replace(/\.[^.]+$/, '').replace(/[^a-zA-Z0-9_-]/g, '_');
const ts          = new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-');

// Create output directories for every platform
platformsCfg.platforms.forEach(p => {
  const dir = path.join('/data/media/output', ts, p.name);
  fs.mkdirSync(dir, { recursive: true });
});

// Return one item per platform — all carry the original image binary
return platformsCfg.platforms.map(p => ({
  json: {
    platform:          p.name,
    width:             p.w,
    height:            p.h,
    watermark_text:    watermarkCfg.text        || '',
    watermark_size:    watermarkCfg.font_size   || 32,
    watermark_color:   watermarkCfg.color       || '#ffffff',
    watermark_x:       watermarkCfg.position_x  || 24,
    watermark_y:       watermarkCfg.position_y  || 24,
    orig_name:         origName,
    ts:                ts,
    output_path:       `/data/media/output/${ts}/${p.name}/${origName}_${p.name}.jpg`
  },
  binary: { data: imageBinary }
}));

// Collect all saved files and return a summary
const items = $input.all();
const saved = items.map(i => i.json.output_path);
const first = items[0]?.json || {};

return [{
  json: {
    status:    'done',
    total:     saved.length,
    folder:    `/data/media/output/${first.ts}/`,
    platforms: items.map(i => ({
      name: i.json.platform,
      size: `${i.json.width}x${i.json.height}`,
      file: i.json.output_path.split('/').pop()
    }))
  }
}];
